#!/usr/bin/env node
// Writes the card network marks of packages/ui (card-brand-icons.ts) as
// Android vector drawables, for the brand on a card's keyboard chip.
// Generated files are committed; rerun after the marks change:
//   node scripts/build-android-card-brands.mjs
import { writeFileSync } from "node:fs";
import { CARD_BRAND_IDS, CARD_BRAND_ICONS } from "../packages/ui/src/card-brand-icons.ts";

const out = new URL("../apps/android/app/src/main/res/drawable/", import.meta.url);

for (const id of CARD_BRAND_IDS) {
  const { viewBox, shapes } = CARD_BRAND_ICONS[id];
  const [, , w, h] = viewBox.split(" ").map(Number);
  const paths = shapes.map((s) => {
    if (!s.d) throw new Error(`${id}: only path shapes are supported`);
    return `    <path\n        android:fillColor="${s.fill}"\n        android:pathData="${s.d}" />`;
  });
  const xml = `<?xml version="1.0" encoding="utf-8"?>
<!-- Generated by scripts/build-android-card-brands.mjs from packages/ui/src/card-brand-icons.ts
     (Apache-2.0, see THIRD-PARTY-NOTICES.md). Do not edit. -->
<vector xmlns:android="http://schemas.android.com/apk/res/android"
    android:width="${(w / h) * 24}dp"
    android:height="24dp"
    android:viewportWidth="${w}"
    android:viewportHeight="${h}">
${paths.join("\n")}
</vector>
`;
  writeFileSync(new URL(`ic_brand_${id}.xml`, out), xml);
}
